    status = obs.get('status', '')
    hitch = obs.get('hitch_deg', 0.0)
    # If we are pinned or stopped after a touch, pull forward to straighten the trailer
    if status in ('PINNED', 'STOPPED'):
        steer = max(-45.0, min(45.0, hitch))  # steer toward the side the trailer is swinging
        speed = 1.5  # moderate forward speed to recover
        look = -30.0 if hitch < 0 else 30.0
        return {'steer_deg': steer, 'speed_mps': speed, 'look_deg': look}
    # While reversing, keep the trailer straight; slow down if hitch angle is large
    if status == 'REVERSING':
        steer = max(-45.0, min(45.0, hitch))  # steer to reduce hitch angle
        speed = -0.5 if abs(hitch) > 15.0 else -1.0
        if hitch > 2.0:
            look = 30.0
        elif hitch < -2.0:
            look = -30.0
        else:
            look = 0.0
        return {'steer_deg': steer, 'speed_mps': speed, 'look_deg': look}
    # Fallback: move forward slowly
    steer = max(-45.0, min(45.0, hitch))
    speed = 1.0
    look = 0.0
    return {'steer_deg': steer, 'speed_mps': speed, 'look_deg': look}

