def control(obs):
    # Controller to straighten trailer by pulling forward, then resume reversing
    status = obs.get('status','')
    hitch = obs.get('hitch_deg',0.0)
    # Helper to clamp steering to vehicle limits
    def clamp(v):
        return max(-45.0, min(45.0, v))
    # Forward recovery when pinned or stopped
    if status in ('PINNED','STOPPED'):
        steer = clamp(hitch)            # steer toward the side the trailer is swinging
        speed = 2.0                      # strong forward speed (within max 4 m/s)
        look = -30.0 if hitch < 0 else 30.0  # look opposite side to keep rail in view
        return {'steer_deg': steer, 'speed_mps': speed, 'look_deg': look}
    # Normal reversing phase
    if status == 'REVERSING':
        # If trailer is near straight, reverse at normal speed; otherwise reverse gently
        speed = -1.0 if abs(hitch) < 5.0 else -0.5
        steer = clamp(-hitch)            # steer opposite to hitch to correct it while reversing
        look = 0.0
        return {'steer_deg': steer, 'speed_mps': speed, 'look_deg': look}
    # Fallback: small forward crawl
    steer = clamp(hitch)
    speed = 0.5
    look = 0.0
    return {'steer_deg': steer, 'speed_mps': speed, 'look_deg': look}

