import math
MAX_STEER = 45.0

# Simple state‑machine controller for trailer reversing
#  • If the vehicle is stopped, start reversing at the default reverse speed.
#  • While reversing, steer proportionally to the hitch angle (positive hitch -> steer left) to bring the trailer back to straight.
#  • If the hitch angle approaches the mechanical limit or the status becomes JACKKNIFED, switch to forward motion to straighten the trailer.
#  • Otherwise, keep the vehicle stopped.

def control(obs):
    status = obs.get('status')
    hitch = obs.get('hitch_deg', 0.0)

    # Start reversing from a stopped state
    if status == 'STOPPED':
        return (0.0, -obs['speed']['default_rev'])

    # If we are jackknifed or the hitch angle is dangerously large, pull forward to reset
    if status == 'JACKKNIFED' or abs(hitch) > 75.0:
        return (0.0, obs['speed']['default_fwd'])

    # Normal reversing: steer to reduce hitch angle
    if status in ('REVERSING', 'READY', 'PULLING_FORWARD'):
        steer = max(-MAX_STEER, min(MAX_STEER, hitch))
        return (steer, -obs['speed']['default_rev'])

    # Fallback: stop
    return (0.0, 0.0)

